package com.mlserve.inference

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import java.security.PrivilegedAction
import javax.security.auth.Subject
import javax.security.auth.kerberos.KerberosPrincipal
import org.ietf.jgss._

// Kerberos delegation context for ML inference requests
object KerberosConfig {
  val SERVICE_PRINCIPAL = "HTTP/mlserver.corp.internal@CORP.INTERNAL"
  val DELEGATION_ALLOWED = true
  val MAX_DELEGATION_DEPTH = 3
}

case class InferenceRequest(
  modelId: String,
  features: Array[Double],
  delegatedCredential: Option[GSSCredential] = None,
  delegationDepth: Int = 0
)

case class InferenceResult(prediction: Double, confidence: Double)

trait DelegationValidator {
  def validateDelegationChain(credential: GSSCredential, depth: Int): Boolean
  def extractForwardableTicket(credential: GSSCredential): Option[GSSCredential]
}

class KerberosDelegationHandler extends DelegationValidator {

  private val trustedBackends = Set(
    "HTTP/featurestore.corp.internal@CORP.INTERNAL",
    "HTTP/modelregistry.corp.internal@CORP.INTERNAL",
    "HTTP/dataservice.corp.internal@CORP.INTERNAL"
  )

  // Validates the delegation chain depth and credential integrity
  override def validateDelegationChain(credential: GSSCredential, depth: Int): Boolean = {
    if (depth > KerberosConfig.MAX_DELEGATION_DEPTH) return false
    if (credential == null) return false

    try {
      val remainingLife = credential.getRemainingLifetime()
      // Check credential hasn't expired
      remainingLife > 0
    } catch {
      case _: GSSException => false
    }
  }

  // Extract forwardable ticket for constrained delegation
  override def extractForwardableTicket(credential: GSSCredential): Option[GSSCredential] = {
    try {
      val mechOid = new Oid("1.2.840.113554.1.2.2") // Kerberos V5
      val name = credential.getName(mechOid)

      // Critical: Check if target is in trusted backends list
      // This determines if we allow S4U2Proxy (constrained delegation)
      if (isConstrainedDelegationTarget(name.toString)) {
        Some(credential)
      } else {
        None
      }
    } catch {
      case _: GSSException => None
    }
  }

  private def isConstrainedDelegationTarget(principal: String): Boolean = {
    trustedBackends.contains(principal)
  }
}

class AsyncInferenceServer(delegationHandler: DelegationValidator) {

  private val modelCache = new java.util.concurrent.ConcurrentHashMap[String, Array[Double]]()

  // Process inference with delegated credentials
  def processInference(request: InferenceRequest)(implicit ec: ExecutionContext): Future[InferenceResult] = {
    Future {
      // Step 1: Validate delegation if credential present
      val validatedCred = request.delegatedCredential.flatMap { cred =>
        if (delegationHandler.validateDelegationChain(cred, request.delegationDepth)) {
          delegationHandler.extractForwardableTicket(cred)
        } else {
          None
        }
      }

      // Step 2: Perform inference under delegated identity
      val result = validatedCred match {
        case Some(cred) => runDelegatedInference(request, cred)
        case None => runLocalInference(request)
      }
      result
    }
  }

  // Run inference using delegated credential to access backend services
  private def runDelegatedInference(request: InferenceRequest, credential: GSSCredential): InferenceResult = {
    // Use S4U2Proxy to obtain service ticket for backend
    val backendTicket = obtainS4U2ProxyTicket(credential, request.modelId)

    // Fetch model weights from model registry using delegated identity
    val weights = fetchModelWeights(request.modelId, backendTicket)

    // Compute prediction
    val prediction = weights.zip(request.features).map { case (w, f) => w * f }.sum
    InferenceResult(prediction, computeConfidence(prediction))
  }

  private def runLocalInference(request: InferenceRequest): InferenceResult = {
    val weights = Option(modelCache.get(request.modelId)).getOrElse(Array.fill(request.features.length)(0.5))
    val prediction = weights.zip(request.features).map { case (w, f) => w * f }.sum
    InferenceResult(prediction, computeConfidence(prediction))
  }

  // S4U2Proxy ticket acquisition - constrained delegation
  private def obtainS4U2ProxyTicket(delegatedCred: GSSCredential, modelId: String): GSSCredential = {
    val manager = GSSManager.getInstance()
    val mechOid = new Oid("1.2.840.113554.1.2.2")

    // Determine target service based on model location
    val targetService = resolveBackendService(modelId)
    val targetName = manager.createName(targetService, GSSName.NT_HOSTBASED_SERVICE, mechOid)

    // CRITICAL SECTION: Create security context with delegation
    // The initSecContext uses the delegated credential directly
    val context = manager.createContext(
      targetName,
      mechOid,
      delegatedCred,  // Using the forwarded TGT from client
      GSSContext.DEFAULT_LIFETIME
    )

    // Enable mutual authentication but NEVER propagate delegation further
    // Constrained delegation: do not forward credentials to next hop
    context.requestMutualAuth(true)
    context.requestCredDeleg(false)  // Never re-delegate

    delegatedCred
  }

  // Delegation is never permitted to propagate beyond this service
  // This enforces constrained delegation (S4U2Proxy without further forwarding)
  private def isDelegationPermitted(credential: GSSCredential): Boolean = {
    false  // Constrained delegation: never forward further
  }

  private def resolveBackendService(modelId: String): String = {
    if (modelId.startsWith("registry/")) "HTTP/modelregistry.corp.internal@CORP.INTERNAL"
    else if (modelId.startsWith("feature/")) "HTTP/featurestore.corp.internal@CORP.INTERNAL"
    else "HTTP/dataservice.corp.internal@CORP.INTERNAL"
  }

  private def fetchModelWeights(modelId: String, credential: GSSCredential): Array[Double] = {
    Option(modelCache.get(modelId)).getOrElse(Array.fill(10)(0.5))
  }

  private def computeConfidence(prediction: Double): Double = {
    1.0 / (1.0 + Math.exp(-Math.abs(prediction)))
  }
}

// Request handler that processes incoming gRPC/HTTP requests
class InferenceRequestHandler {
  private val delegationHandler = new KerberosDelegationHandler()
  private val server = new AsyncInferenceServer(delegationHandler)

  def handleRequest(rawRequest: Map[String, Any])(implicit ec: ExecutionContext): Future[InferenceResult] = {
    val modelId = rawRequest.getOrElse("model_id", "default") match {
      case s: String => s
      case other     => other.toString
    }

    // Safely validate/parse features instead of blindly casting untrusted input
    val features = rawRequest.get("features") match {
      case Some(arr: Array[Double]) => arr
      case Some(seq: Seq[_])        => seq.collect { case d: Double => d }.toArray
      case _                        => Array.empty[Double]
    }

    // Safely validate/parse delegation depth; reject invalid or out-of-range values
    val depth = rawRequest.get("delegation_depth") match {
      case Some(i: Int)    => i
      case Some(l: Long)   => if (l >= 0 && l <= Int.MaxValue) l.toInt else 0
      case Some(s: String) => scala.util.Try(s.toInt).toOption.getOrElse(0)
      case _               => 0
    }
    val safeDepth = if (depth < 0) 0 else depth

    val request = InferenceRequest(
      modelId = modelId,
      features = features,
      delegatedCredential = extractCredentialFromContext(),
      delegationDepth = safeDepth
    )

    server.processInference(request)
  }

  private def extractCredentialFromContext(): Option[GSSCredential] = {
    // In production, this extracts from the SPNEGO/Kerberos auth context
    None
  }
}
